import {encode} from './encoding.js';
let step=0;const input=document.querySelector('#message');const steps=[...document.querySelectorAll('[data-step]')];
function letters(sequence,damage=false){const fragment=document.createDocumentFragment();for(const [i,b]of [...sequence].entries()){const s=document.createElement('span');s.className='letter'+(damage&&i%13===4?' damaged':'');s.dataset.base=b;s.textContent=b;fragment.append(s);}return fragment;}
function render(){let bytes=new TextEncoder().encode(input.value);while(bytes.length>24){input.value=input.value.slice(0,-1);bytes=new TextEncoder().encode(input.value);}document.querySelector('#byte-count').textContent=`${bytes.length} BYTES`;const art=document.querySelector('#stage-art');art.replaceChildren();const titles=['Every file starts as numbers.','Same message. A new alphabet.','What if some letters go missing?','The goal: exactly the same file.'];const descriptions=['Your words become bytes: small numbers a computer can store. Images, songs and documents can be represented as bytes too.','This live example maps each pair of binary digits to A, C, G or T. The full compiler adds constraints, identifiers and error-correction data.','Here we mark a few letters as damaged. The real testbench can change letters, insert or delete them, or lose entire strands.','Helix uses repair data to try to reconstruct the original bytes, then checks the whole file with SHA-256. If recovery fails, it reports failure.'];document.querySelector('#stage-label').textContent=['01 / YOUR ORIGINAL MESSAGE','02 / A SIMPLE DNA ENCODING','03 / ILLUSTRATED DAMAGE','04 / ILLUSTRATED RECOVERY'][step];document.querySelector('#stage-title').textContent=titles[step];document.querySelector('#stage-description').textContent=descriptions[step];if(step===0||step===3){const p=document.createElement('span');p.className='message-art';p.textContent=(step===3?'✓ ':'')+(input.value||'Your message');art.append(p);}else art.append(letters(encode(bytes),step===2));steps.forEach((b,i)=>b.setAttribute('aria-pressed',String(step===i)));document.querySelector('#next').textContent=step===3?'Start again ↺':'Next step →';}
steps.forEach(b=>b.addEventListener('click',()=>{step=Number(b.dataset.step);render();}));input.addEventListener('input',render);document.querySelector('#next').addEventListener('click',()=>{step=(step+1)%4;render();});render();
for(const button of document.querySelectorAll('[data-mode]'))button.addEventListener('click',()=>{document.querySelectorAll('[data-mode]').forEach(b=>b.setAttribute('aria-pressed',String(b===button)));renderConstraint(button.dataset.mode==='constrained');});
function renderConstraint(constrained){const sequence=encode(new Uint8Array(8),constrained);document.querySelector('#constraint-sequence').replaceChildren(letters(sequence));document.querySelector('#nt').textContent=sequence.length;document.querySelector('#run').textContent=Math.max(...[...sequence.matchAll(/(.)\1*/g)].map(m=>m[0].length));document.querySelector('#density').textContent=(64/sequence.length).toFixed(1);}renderConstraint(false);
const reduced=matchMedia('(prefers-reduced-motion: reduce)');let paused=reduced.matches;const pause=document.querySelector('#motion');function pauseLabel(){pause.textContent=paused?'Resume rotation ▷':'Pause rotation Ⅱ';pause.setAttribute('aria-pressed',String(paused));}pauseLabel();pause.addEventListener('click',()=>{paused=!paused;pauseLabel();});reduced.addEventListener('change',e=>{paused=e.matches;pauseLabel();});
async function scene(){try{const THREE=await import('./vendor/three.module.js');const host=document.querySelector('#molecule');const renderer=new THREE.WebGLRenderer({alpha:true,antialias:true});renderer.setPixelRatio(Math.min(devicePixelRatio,1.7));renderer.setClearColor(0,0);renderer.domElement.setAttribute('aria-hidden','true');renderer.domElement.style.touchAction='pan-y';host.prepend(renderer.domElement);const world=new THREE.Scene();const camera=new THREE.PerspectiveCamera(36,1,.1,100);camera.position.set(0,0,19);world.add(new THREE.AmbientLight(0xffffff,2));const light=new THREE.DirectionalLight(0xfff8df,3);light.position.set(5,8,8);world.add(light);const group=new THREE.Group();group.rotation.z=-.34;world.add(group);const colors=[0x79986c,0xbb946b,0xd5b85c,0x688e91];const sphere=new THREE.SphereGeometry(.16,14,10);const materials=colors.map(color=>new THREE.MeshStandardMaterial({color,roughness:.55}));const rail=new THREE.MeshStandardMaterial({color:0x849b73,roughness:.55});const bond=new THREE.MeshStandardMaterial({color:0xd2c5a7,roughness:.6});function cylinder(a,b,r,mat){const delta=new THREE.Vector3().subVectors(b,a);const mesh=new THREE.Mesh(new THREE.CylinderGeometry(r,r,delta.length(),8),mat);mesh.position.copy(a).add(b).multiplyScalar(.5);mesh.quaternion.setFromUnitVectors(new THREE.Vector3(0,1,0),delta.normalize());group.add(mesh);}let prev=[];for(let i=0;i<32;i++){const angle=i*.40,y=(i-15.5)*.29;const pair=[new THREE.Vector3(Math.cos(angle)*1.3,y,Math.sin(angle)*1.3),new THREE.Vector3(-Math.cos(angle)*1.3,y,-Math.sin(angle)*1.3)];pair.forEach((p,j)=>{const mesh=new THREE.Mesh(sphere,materials[(i+j*2)%4]);mesh.position.copy(p);group.add(mesh);if(prev[j])cylinder(prev[j],p,.055,rail);});cylinder(pair[0],pair[1],.055,bond);prev=pair;}host.querySelector('.fallback').style.display='none';const observer=new ResizeObserver(()=>{const w=host.clientWidth,h=host.clientHeight;renderer.setSize(w,h);camera.aspect=w/h;camera.updateProjectionMatrix();});observer.observe(host);let drag=false,x=0;renderer.domElement.addEventListener('pointerdown',e=>{drag=true;x=e.clientX;renderer.domElement.setPointerCapture(e.pointerId);});renderer.domElement.addEventListener('pointermove',e=>{if(drag){group.rotation.y+=(e.clientX-x)*.012;x=e.clientX;}});renderer.domElement.addEventListener('pointerup',()=>drag=false);renderer.domElement.addEventListener('pointercancel',()=>drag=false);let visible=true;new IntersectionObserver(e=>visible=e[0].isIntersecting).observe(host);let last=0;renderer.setAnimationLoop(t=>{if(visible&&!document.hidden){if(!paused&&!drag)group.rotation.y+=Math.min((t-last)/1000,.05)*.18;renderer.render(world,camera);}last=t;});}catch{document.querySelector('.scene-caption').textContent='DNA illustration · interactive 3D unavailable';pause.hidden=true;}}
scene();
